def _parse_harness_jsonl_specs(specs: list[str] | None) -> tuple[dict[str, list[Path]], str | None]:
    harness_by_branch: dict[str, list[Path]] = {}
    for spec in specs or []:
        if "=" not in spec:
            return {}, f"--harness-jsonl expects BRANCH=PATH, got {spec!r}"
        branch, path = spec.split("=", 1)
        if not branch:
            return {}, f"--harness-jsonl expects non-empty BRANCH in {spec!r}"
        if not path:
            return {}, f"--harness-jsonl expects non-empty PATH in {spec!r}"
        harness_by_branch.setdefault(branch, []).append(Path(path))
    return harness_by_branch, None


def _message_role(rec: dict) -> str:
    if isinstance(rec.get("message"), dict):
        role = rec["message"].get("role")
        if isinstance(role, str):
            return role
    if isinstance(rec.get("payload"), dict):
        role = rec["payload"].get("role")
        if isinstance(role, str):
            return role
        payload_type = rec["payload"].get("type")
        if payload_type == "agent_message":
            return "assistant"
        if payload_type == "user_message":
            return "user"
    role = rec.get("role")
    if isinstance(role, str):
        return role
    rec_type = rec.get("type")
    return rec_type if isinstance(rec_type, str) else ""


def _record_timestamp(rec: dict) -> str:
    for key in ("timestamp", "created_at", "time"):
        value = rec.get(key)
        if isinstance(value, str) and value:
            return value
    message = rec.get("message")
    if isinstance(message, dict):
        for key in ("timestamp", "created_at", "time"):
            value = message.get(key)
            if isinstance(value, str) and value:
                return value
    return ""


def _parse_iso(ts: str) -> datetime | None:
    if not ts:
        return None
    # Tolerate a trailing Z (the Codex session logs use UTC `…Z` stamps,
    # which datetime.fromisoformat doesn't accept before 3.11).
    try:
        return datetime.fromisoformat(ts.replace("Z", "+00:00"))
    except ValueError:
        return None


def _jsonl_duration_seconds(path: Path) -> float:
    """Wall-clock span of a session JSONL, from its first to its last
    parseable record timestamp. 0.0 if the file is missing or has fewer
    than two timestamps."""
    if not path.exists():
        return 0.0
    first: datetime | None = None
    last: datetime | None = None
    try:
        with path.open() as f:
            for line in f:
                try:
                    rec = json.loads(line)
                except json.JSONDecodeError:
                    continue
                dt = _parse_iso(_record_timestamp(rec))
                if dt is None:
                    continue
                if first is None:
                    first = dt
                last = dt
    except OSError:
        return 0.0
    if first is None or last is None:
        return 0.0
    return max(0.0, (last - first).total_seconds())


def _text_from_content_value(value) -> list[str]:
    if isinstance(value, str):
        return [value]
    if isinstance(value, list):
        out: list[str] = []
        for item in value:
            if isinstance(item, str):
                out.append(item)
            elif isinstance(item, dict):
                out.extend(_text_from_content_value(item.get("text")))
                out.extend(_text_from_content_value(item.get("content")))
                out.extend(_text_from_content_value(item.get("output")))
                out.extend(_text_from_content_value(item.get("result")))
        return out
    if isinstance(value, dict):
        out: list[str] = []
        for key in ("text", "content", "output", "result", "stdout", "stderr", "message"):
            out.extend(_text_from_content_value(value.get(key)))
        return out
    return []


def _iter_codex_payload_texts(rec: dict):
    payload = rec.get("payload")
    if not isinstance(payload, dict):
        return
    payload_type = payload.get("type")
    if payload_type == "message":
        role = payload.get("role")
        context = role if role in {"assistant", "user"} else "message"
        for text in _text_from_content_value(payload.get("content")):
            yield context, text
    elif payload_type in {"function_call_output", "tool_result"}:
        for text in _text_from_content_value(payload):
            yield "tool_result", text
    elif payload_type == "agent_message":
        for text in _text_from_content_value(payload.get("message")):
            yield "assistant", text
    elif payload_type == "user_message":
        for text in _text_from_content_value(payload.get("message")):
            yield "user", text


def _iter_harness_texts(rec: dict):
    """Yield `(context, text)` from assistant text and tool-result payloads."""
    role = _message_role(rec)
    rec_type = rec.get("type")
    yield from _iter_codex_payload_texts(rec)
    if role == "assistant":
        message = rec.get("message")
        content = message.get("content") if isinstance(message, dict) else rec.get("content")
        if isinstance(content, list):
            for entry in content:
                if not isinstance(entry, dict):
                    continue
                entry_type = entry.get("type")
                if entry_type == "text":
                    for text in _text_from_content_value(entry.get("text")):
                        yield "assistant", text
                elif entry_type in {"tool_result", "function_call_output"}:
                    for text in _text_from_content_value(entry):
                        yield "tool_result", text
        else:
            for text in _text_from_content_value(content):
                yield "assistant", text

    if rec_type in {"tool_result", "function_call_output"}:
        for text in _text_from_content_value(rec):
            yield "tool_result", text

    message = rec.get("message")
    content = message.get("content") if isinstance(message, dict) else rec.get("content")
    if role != "assistant" and isinstance(content, list):
        for entry in content:
            if isinstance(entry, dict) and entry.get("type") in {
                "tool_result",
                "function_call_output",
            }:
                for text in _text_from_content_value(entry):
                    yield "tool_result", text

    if rec_type in {"tool_result", "function_call_output"}:
        return

    for key in ("stdout", "stderr", "output", "result"):
        for text in _text_from_content_value(rec.get(key)):
            yield "tool_result", text


_EXPLICIT_SKILL_ISSUE_RE = re.compile(
    r"\b(?:skill|instructions?)\b.{0,80}\b(?:bug|broken|wrong|incorrect|inconsistent|contradictory)\b"
    r"|\b(?:bug|broken|wrong|incorrect|inconsistent|contradictory)\b.{0,80}\b(?:skill|instructions?)\b",
    re.IGNORECASE,
)

_CONFIRMATION_GATE_RE = re.compile(
    r"\b(?:want me to|should i proceed|shall i proceed|if you want me to|let me know if you want)\b",
    re.IGNORECASE,
)


def _collapse_ws(text: str) -> str:
    return " ".join(text.split())


def _clip_evidence(text: str, limit: int = 240) -> str:
    evidence = _collapse_ws(text)
    if len(evidence) <= limit:
        return evidence
    return evidence[: limit - 3].rstrip() + "..."


def _local_text_windows(text: str, radius: int = 4) -> list[str]:
    lines = [_collapse_ws(line) for line in text.splitlines() if line.strip()]
    if not lines:
        collapsed = _collapse_ws(text)
        return [collapsed] if collapsed else []
    out: list[str] = []
    for i in range(len(lines)):
        start = max(0, i - radius)
        end = min(len(lines), i + radius + 1)
        out.append(" ".join(lines[start:end]))
    return out


def _has_autocuda_context(text: str) -> bool:
    lower = text.lower()
    return (
        "autocuda " in lower
        or "autocuda:" in lower
        or "autocuda/" in lower
        or "/autocuda:" in lower
    )


def _infer_skill_hint(branch: str, text: str) -> str:
    for pattern in (
        r"/autocuda:([a-z0-9_-]+)",
        r"\bautocuda\s+report\s+data\s+([a-z0-9_-]+)\b",
        r"\bautocuda\s+schema\s+check\s+report-([a-z0-9_-]+)-(?:csv|markdown)\b",
        r"\bautocuda\s+log\s+(optimize-tree|optimize|combine|crawl)(?=\s|$)",
    ):
        match = re.search(pattern, text, re.IGNORECASE)
        if match:
            value = match.group(1).lower()
            if value.startswith("report-"):
                return value
            if pattern.startswith(r"\bautocuda\s+report") or "schema" in pattern:
                return f"report-{value}"
            if value == "optimize":
                return "optimize-simple"
            return value
    if "/brief-" in branch and "/optimize/" in branch:
        return "optimize-tree"
    if branch.startswith("autocuda/"):
        parts = branch.split("/")
        if len(parts) > 1:
            if parts[1] == "optimize":
                return "optimize-simple"
            return parts[1]
    return ""


def _skill_issue_signals_from_text(text: str, context: str) -> list[dict]:
    signals: list[dict] = []
    seen: set[tuple[str, str]] = set()

    def add(window: str, data: dict) -> None:
        key = (data["category"], window)
        if key in seen:
            return
        seen.add(key)
        data["evidence"] = _clip_evidence(window)
        signals.append(data)

    for window in _local_text_windows(text):
        lower = window.lower()
        has_autocuda = _has_autocuda_context(window)

        if has_autocuda and "traceback (most recent call last)" in lower:
            add(
                window,
                {
                    "severity": "critical",
                    "category": "autocuda_exception",
                    "signal": "autocuda command raised an exception",
                    "recommendation": "Fix the CLI or skill call path that produced the traceback.",
                },
            )
        if has_autocuda and any(
            needle in lower
            for needle in (
                "invalid choice:",
                "unrecognized arguments:",
                "the following arguments are required:",
                "error: argument",
            )
        ):
            add(
                window,
                {
                    "severity": "high",
                    "category": "autocuda_cli_contract",
                    "signal": "autocuda CLI rejected a skill-issued command",
                    "recommendation": "Update the skill prose and examples to match the current CLI surface.",
                },
            )
        if has_autocuda and any(
            needle in lower
            for needle in (
                "header mismatch",
                "missing or out-of-order section",
                "is missing a table with columns",
                "does not match the built-in report",
            )
        ):
            add(
                window,
                {
                    "severity": "high",
                    "category": "schema_contract",
                    "signal": "Report or log schema validation failed",
                    "recommendation": "Fix the producing skill so generated artifacts match the built-in schema.",
                },
            )
        if has_autocuda and "command not found" in lower:
            add(
                window,
                {
                    "severity": "medium",
                    "category": "autocuda_unavailable",
                    "signal": "autocuda CLI was not on PATH during the run",
                    "recommendation": "Fix setup instructions so the skill verifies the CLI before starting work.",
                },
            )
        if context == "assistant" and _EXPLICIT_SKILL_ISSUE_RE.search(window):
            add(
                window,
                {
                    "severity": "high",
                    "category": "explicit_skill_issue",
                    "signal": "Agent identified a bug or contradiction in skill instructions",
                    "recommendation": "Patch the named SKILL.md or referenced guide, then add a regression check when possible.",
                },
            )
        if context == "assistant" and _CONFIRMATION_GATE_RE.search(window):
            add(
                window,
                {
                    "severity": "medium",
                    "category": "operator_confirmation_gate",
                    "signal": "Agent asked for confirmation instead of continuing the instructed run",
                    "recommendation": "Tighten the invoking skill so the original operator instruction is treated as the greenlight.",
                },
            )
    return signals


def _collect_skill_issue_incidents(branch: str, path: Path) -> list[dict]:
    if not path.exists():
        return [
            {
                "branch": branch,
                "skill": _infer_skill_hint(branch, ""),
                "timestamp": "",
                "severity": "info",
                "category": "missing_harness",
                "signal": "No harness JSONL was available for automated skill issue scanning",
                "evidence": str(path),
                "recommendation": "Attach the session JSONL under autocuda/harness-records and re-run the report.",
                "source": str(path),
            }
        ]

    rows: list[dict] = []
    seen: set[tuple[str, str, str, str]] = set()
    try:
        with path.open(encoding="utf-8", errors="replace") as f:
            for line_no, line in enumerate(f, start=1):
                if not line.strip():
                    continue
                try:
                    rec = json.loads(line)
                except json.JSONDecodeError as exc:
                    rows.append(
                        {
                            "branch": branch,
                            "skill": _infer_skill_hint(branch, ""),
                            "timestamp": "",
                            "severity": "low",
                            "category": "harness_parse_error",
                            "signal": "Harness JSONL line could not be parsed",
                            "evidence": f"line {line_no}: {exc.msg}",
                            "recommendation": "Fix or replace the harness record before relying on the report.",
                            "source": str(path),
                        }
                    )
                    continue

                timestamp = _record_timestamp(rec)
                for context, text in _iter_harness_texts(rec):
                    for signal in _skill_issue_signals_from_text(text, context):
                        source_key = f"{path}:{line_no}:{context}"
                        evidence = f"line {line_no} ({context}): {signal['evidence']}"
                        key = (signal["category"], signal["signal"], evidence, source_key)
                        if key in seen:
                            continue
                        seen.add(key)
                        rows.append(
                            {
                                "branch": branch,
                                "skill": _infer_skill_hint(branch, text),
                                "timestamp": timestamp,
                                "severity": signal["severity"],
                                "category": signal["category"],
                                "signal": signal["signal"],
                                "evidence": evidence,
                                "recommendation": signal["recommendation"],
                                "source": str(path),
                            }
                        )
    except (OSError, UnicodeDecodeError) as exc:
        rows.append(
            {
                "branch": branch,
                "skill": _infer_skill_hint(branch, ""),
                "timestamp": "",
                "severity": "info",
                "category": "missing_harness",
                "signal": "Harness JSONL could not be read",
                "evidence": str(exc),
                "recommendation": "Attach a readable session JSONL and re-run the report.",
                "source": str(path),
            }
        )
    return rows


def cmd_report_build_skill(args: argparse.Namespace) -> int:
    """Skill report data from harness records.

    The CSV contains candidate incidents, not final verdicts. The
    `report-skill` skill reviews each row against the run context
    and decides whether the evidence points at a bug in an autocuda
    skill, a setup problem, or a harmless failed experiment.
    """
    m = _autocuda_cli_module()
    repo = _resolve_repo(args)
    harness_by_branch, error = _parse_harness_jsonl_specs(args.harness_jsonl)
    if error:
        print(error, file=sys.stderr)
        return 2

    if getattr(args, "tag", None):
        try:
            target_branches = _resolve_target_branches(args, repo)
        except ValueError as exc:
            print(f"error: {exc}", file=sys.stderr)
            return 2
        branches = sorted({*target_branches, *harness_by_branch})
    elif harness_by_branch:
        branches = sorted(harness_by_branch)
    else:
        branches = _resolve_target_branches(args, repo)

    if not branches:
        print(
            "no experiment branches or --harness-jsonl records found and none passed via --tag",
            file=sys.stderr,
        )
        return 2
    output = _resolve_report_output(args)

    rows: list[dict] = []
    for branch in branches:
        paths = harness_by_branch.get(branch)
        if not paths:
            rows.append(
                {
                    "branch": branch,
                    "skill": _infer_skill_hint(branch, ""),
                    "timestamp": "",
                    "severity": "info",
                    "category": "missing_harness",
                    "signal": "No harness JSONL was available for automated skill issue scanning",
                    "evidence": "",
                    "recommendation": "Pass --harness-jsonl BRANCH=PATH for this branch and re-run the report.",
                    "source": "",
                }
            )
            continue
        for path in paths:
            rows.extend(_collect_skill_issue_incidents(branch, path))

    for i, row in enumerate(rows):
        row["incident_id"] = f"bug_{i:04d}"

    out = m.report_path(args.experiments, "report-skill", output, "csv")
    _write_report_csv(out, rows, m.REPORT_SCHEMAS["report-skill"])
    print(f'OUTPUT="{output}"')
    print(f"wrote {out} with {len(rows)} skill issue candidate(s)", file=sys.stderr)
    return 0


