def brief_log_path(experiments_dir: Path, tag: str, brief_id: str | int) -> Path:
    """`<dir>/<tag>-optimize-tree-brief-<K>-log.csv` — one brief id's log."""
    return experiments_dir / f"{tag}-optimize-tree-brief-{brief_id}-log.csv"


def reference_log_path(experiments_dir: Path, tag: str) -> Path:
    """`<dir>/<tag>-optimize-tree-reference-log.csv` — the run's baseline
    (and, on a simplify run, optimized) reference rows in a single file."""
    return experiments_dir / f"{tag}-optimize-tree-reference-log.csv"


def all_brief_log_paths(experiments_dir: Path, tag: str) -> list[Path]:
    """Every per-brief optimize-tree log for `tag`, sorted numerically by
    brief id. The reference log is excluded — it has no brief number;
    callers that need it read `reference_log_path`."""
    rows = list(experiments_dir.glob(f"{tag}-optimize-tree-brief-*-log.csv"))

    def _bid(p: Path) -> int:
        match = TREE_BRIEF_LOG_RE.search(p.name)
        return int(match.group(1)) if match else -1

    return sorted(rows, key=_bid)


def crawl_log_file_path(experiments_dir: Path, tag: str) -> Path:
    return experiments_dir / f"{tag}-crawl-log.csv"


def report_path(experiments_dir: Path, kind: str, output: str, ext: str) -> Path:
    """`<dir>/<output>-<kind>.<ext>` — report file.

    `kind` is the full report kind (e.g. `report-optimization`); `ext` is
    `csv`, `md`, or `html`. Every report run picks one `<output>` name and
    uses it for all three files.
    """
    return experiments_dir / f"{output}-{kind}.{ext}"


def parse_benchmark_spec(spec: str) -> dict:
    """Parse 'name:unit:direction:precision' into a dict."""
    parts = spec.split(":")
    if len(parts) != 4:
        raise ValueError(f"--benchmark expects NAME:UNIT:DIRECTION:PRECISION, got {spec!r}")
            f"precision must be a non-negative integer, got {precision_str!r}"
        ) from exc
    if precision < 0:
        raise ValueError(f"precision must be non-negative, got {precision}")
    return {"name": name, "unit": unit, "direction": direction, "precision": precision}


def parse_metric_arg(arg: str) -> tuple[str, str]:
    """Parse 'NAME=VALUE' into (name, value)."""
    if "=" not in arg:
        raise ValueError(f"--metric expects NAME=VALUE, got {arg!r}")
    name, value = arg.split("=", 1)
    if not name:
        raise ValueError(f"metric name must not be empty in {arg!r}")
    return name, value


def load_schema(experiments_dir: Path, kind: str = "optimize") -> dict:
    path = schema_path(experiments_dir, kind)
    if not path.exists():
        raise FileNotFoundError(
            f"schema not found at {path}; run `autocuda schema define {kind} ...` first"
        )
    with path.open() as f:
        schema = json.load(f)
    if kind == "optimize":
        if "benchmarks" not in schema or not isinstance(schema["benchmarks"], list):
            raise ValueError(f"schema at {path} is malformed: missing `benchmarks` list")
    elif kind == "crawl":
        if "columns" not in schema or not isinstance(schema["columns"], list):
            raise ValueError(f"schema at {path} is malformed: missing `columns` list")
        if "valid_events" not in schema or not isinstance(schema["valid_events"], list):
            raise ValueError(f"schema at {path} is malformed: missing `valid_events` list")
    return schema


def csv_header_from_schema(schema: dict, skill: str = "optimize") -> list[str]:
    """Header row for a per-skill log CSV.

    `optimize`, `combine`:
        timestamp, trial, <bench_1>, ..., <bench_N>, status, description,
        pct_change

    `optimize-tree-manager`:
        timestamp, brief_id, parent_commits, brief_kind, description

    `optimize-tree-brief`:
        timestamp, brief_id, trial, <bench_1>, ...,
        <bench_N>, status, commit, description

    The reference log shares the `optimize-tree-brief` header. The bare
    `optimize-tree` skill name is rejected — callers must spell out which
    side of the split they want.
    """
    if skill == "optimize-tree-manager":
        return [
            "timestamp",
            "brief_id",
            "parent_commits",
            "brief_kind",
            "description",
        ]
    if skill == "optimize-tree-brief":
        cols = ["timestamp", "brief_id", "trial"]
        cols.extend(b["name"] for b in schema["benchmarks"])
        cols.extend(["status", "commit", "description"])
        return cols
    if skill == "optimize-tree":
        raise ValueError(
            "csv_header_from_schema: `optimize-tree` is split into "
            "`optimize-tree-manager` and `optimize-tree-brief`; pass one explicitly"
        )
    cols = ["timestamp", "trial"]
    cols.extend(b["name"] for b in schema["benchmarks"])
    cols.extend(["status", "description", "pct_change"])
    return cols


