def _default_report_tag() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%d-%H-%M-%S")


def _resolve_report_output(args: argparse.Namespace) -> str:
    """Pick the report output name shared by the CSV / markdown / HTML files.

    Explicit `--output X` wins. Otherwise, a report targeting one tag uses
    that tag as its output name, and every other report uses a fresh
    `<timestamp>-consolidated` name.
    """
    output = (getattr(args, "output", None) or "").strip()
    if output:
        return output
    tags = getattr(args, "tag", None) or []
    if len(tags) == 1:
        return tags[0]
    return f"{_default_report_tag()}-consolidated"


def cmd_report_output(args: argparse.Namespace) -> int:
    """Print the report output name for report skills without a data step."""
    print(f'OUTPUT="{_resolve_report_output(args)}"')
    return 0

